"""CPU-only delivery from EXP-027's independently computed artifacts."""
from pathlib import Path
import csv,json,resource,datetime
P=Path(__file__).resolve().parents[2];E=P/'experiments/EXP-027';R=P/'research';start=resource.getrusage(resource.RUSAGE_SELF)
def j(n):return json.loads((E/n).read_text())
def tab(n):
 with (E/n).open() as f:return list(csv.DictReader(f))
def app(n,s):
 with (R/n).open('a') as f:f.write('\n\n'+s+'\n')
s=j('status.json');assert s['status']=='COMPLETED' and s['validity']=='VALID';locks=j('admission_lock_commit.json');entry=j('evaluation_entry_audit.json');assert locks['sha']==locks['remote_sha']==entry['remote_lock_commit'] and not entry['validator_errors'];fixed=j('fixed_model_manifest.json');after=j('parent_checkpoint_audit.json');assert after['match'] and all(after['model_hashes_after'][g]==fixed['models'][g]['sha256'] for g in fixed['models']);neg=j('admission_negative_tests.json');assert neg['all_passed'] and len(neg['tests'])==7 and all(x['actual_exit_code']==0 for x in neg['tests']);audit=j('actual_candidate_readout_audit.json');par=j('candidate_parameter_audit.json');g=j('hypothesis_gate_results.json');vals=tab('validation_summary.csv');recon=tab('reconstruction_summary.csv');decomp=tab('logit_error_decomposition.csv');boot=j('paired_bootstrap.json');hist=j('historical_reproduction_audit.json');assert all(x['accuracy_delta']==x['CE_delta']==x['FR_delta']==x['SOP_delta']==0 for x in hist['comparisons']);v={x['group']:x for x in vals};pairs={r['group']+' '+r['split']:r for r in recon};d={(x['group'],x['split']):x for x in decomp}
lines=['# EXP-027 固定候选独立准入与性能复核','',f"运行状态：COMPLETED；本轮工程准入：VALID。实际代码 `{s['code_sha']}`；远程准入锁提交 `{locks['sha']}`。EXP-026 保持 INVALID；本轮不重新拟合、不训练、不读取官方测试集。",'','## 对象级准入','一般检查和实际候选检查分别记录，正式评价入口再次验证候选哈希和远程锁；七项负面拒绝测试全部通过。']
for ratio in ['50','75']:
 x=audit[ratio];p=par[ratio];lines.append(f"- {ratio}%：D_grad {x['sample_count']} 张，逐元素比较 {x['compared_elements']}，不一致 {x['mismatch_count']}，最大差 {x['max_abs_difference']}；实际读出归一化误差最大 {x['max_readout_normalized_error']:.3g}。")
 lines.append(f"  实际两模型参数 {p['physical_parameters_R1']}，新增连接 {p['support_added']}，非目标参数/持久化 buffer 差异 {len(p['non_fc2_weight_state_differences'])}；锁定 R120 权重误差 {p['locked_R120_normalized_weight_error']:.3g}。")
lines+=['','## 独立验证结果','| 模型 | Accuracy % | CE | FR_global | SOP/sample | 参数量 |','|---|---:|---:|---:|---:|---:|']
for x in vals:lines.append(f"| {x['group']} | {100*float(x['accuracy']):.5f} | {float(x['CE']):.8f} | {float(x['FR_global']):.8f} | {float(x['SOP_sample_weighted']):.2f} | {x['parameter_count']} |")
lines+=['','## R121 探索性 logits 误差分解','| 模型 | 数据 | 原始 MSE | 中心化 MSE | 公共偏移 MSE | RMSE | 预测一致率 |','|---|---|---:|---:|---:|---:|---:|']
for x in recon:
 y=d[(x['group'],x['split'])];lines.append(f"| {x['group']} | {x['split']} | {float(x['mse']):.8g} | {float(y['MSE_centered']):.8g} | {float(y['MSE_shift']):.8g} | {float(x['rmse']):.8g} | {float(x['prediction_agreement']):.6f} |")
lines+=['','## 预注册门槛及配对统计','50% 是唯一主要条件；75% 为辅助。科学假设正式状态由理论研究员决定。','```json',json.dumps(g,ensure_ascii=False,indent=2),'```','2000 次 PCG64 样本配对 Bootstrap，SOP 配对区间未采集。']
for name,x in boot['comparisons'].items():lines.append(f"- {name}: accuracy {x['accuracy_delta_pp']:.5f} pp，95% CI {x['accuracy_ci95_pp']}；CE {x['CE_delta']:.8f}，95% CI {x['CE_ci95']}；预测差异 {x['prediction_disagreement_count']}。")
lines+=['','## 历史对照及局限','五组 Accuracy、CE、FR_global 及 SOP 相对 EXP-026 探索性结果的差均为 0；本轮每个值重新计算，不能把 EXP-026 变为有效。B0 与 EXP-024 的严格 FP32 Accuracy、CE 和 SOP 也一致。D_grad/D_cal 均来自父模型训练集，D_cal 仅相对本轮历史拟合独立；4500 验证样本多轮开发使用，没有独立训练种子。R121 是事后探索性代数诊断，不更改拟合或门槛。',f"GPU 受控进程墙钟 {s['wall_seconds']:.3f} s，CPU 已测进程树 {s['process_tree_cpu_seconds']:.3f} s；审查开始与 Python 导入前 CPU 未完整测量，计入 90 s 保守预留，详见 resource_usage.csv。墙钟不等于 GPU 内核执行时长或能耗。"]
(E/'REPORT.md').write_text('\n'.join(lines)+'\n');(E/'limitations.md').write_text('''# 局限\n\n- EXP-026 永久 INVALID；独立 EXP-027 的准入不能事后恢复旧实验。\n- 所有模型来自同一训练父模型；不代表独立训练种子或独立测试集确认。D_grad 和 D_cal 均来自父模型训练集。\n- 验证集已多轮用于开发，bootstrap 为样本配对区间，不是模型训练重复；未采集逐样本 SOP，SOP 配对区间 NA。\n- CPU 进程树计数开始在 Python 导入之后，早期只读审查及外部工具进程未全程计数；90 秒是保守预算预留而非测量。GPU 进程墙钟含远程锁定和 CPU 工作，非 GPU 内核执行时间或能耗。\n- 没有调整 lambda、重新拟合或建立新算法；R121 仅为事后误差分解。\n''')
(E/'run.log').write_text('EXP-027-RUN-001: runs/EXP-027-RUN-001/run.log\n')
code=j('code_version.json');code.update(execution_sha=s['code_sha'],admission_lock_commit=locks['sha']);(E/'code_version.json').write_text(json.dumps(code,indent=2)+'\n')
app('RESEARCH_STATE.md','ROUND-025 EXP-027 independent execution COMPLETED with candidate-specific admission VALID; fixed 50% H-026 drop gate false, H-027 all-gates false, 75% auxiliary only. H-026/H-027 remain pending theoretical decision. EXP-026 remains INVALID; no retraining/test set/new method. See ../experiments/EXP-027/REPORT.md.')
with (R/'EXPERIMENT_REGISTRY.csv').open('a',newline='') as f:csv.writer(f,lineterminator='\n').writerow(['EXP-027','EXP-027-RUN-001','ROUND-025','candidate admission and independent replication','H-026;H-027','v0.3.1','research/round-025-admission-replication',s['code_sha'],'','','COMPLETED','UNTESTED','experiments/EXP-027/config.json','experiments/EXP-027/validation_summary.csv','experiments/EXP-027/REPORT.md',datetime.datetime.fromtimestamp(s['start_unix'],datetime.timezone.utc).isoformat(),datetime.datetime.fromtimestamp(s['end_unix'],datetime.timezone.utc).isoformat(),s['wall_seconds'],'object admission lock remote; EXP-026 remains INVALID'])
end=resource.getrusage(resource.RUSAGE_SELF);cpu=(end.ru_utime-start.ru_utime)+(end.ru_stime-start.ru_stime)
with (E/'resource_usage.csv').open('w',newline='') as f:
 w=csv.writer(f,lineterminator='\n');w.writerow(['scope','metric','value','unit','basis','limitation']);w.writerow(['RUN-001','gpu_process_wall',s['wall_seconds'],'seconds','controlled process monotonic-equivalent wall','includes CPU and network; excludes Python imports before clock; not kernel time']);w.writerow(['RUN-001','process_tree_cpu',s['process_tree_cpu_seconds'],'seconds','getrusage and live descendants','starts after Python imports; children sampling can race']);w.writerow(['delivery','self_cpu',cpu,'seconds','getrusage delta','other shell/process CPU not included']);w.writerow(['prelaunch','cpu_reserve',s['cpu_prior_unmeasured_reserve_seconds'],'seconds','conservative reservation','estimated not measured']);w.writerow(['whole','cpu_budget_accounted',s['cpu_budget_accounted_seconds']+cpu,'seconds','measured run plus reserve plus delivery','early tooling CPU not fully measured'])
